// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), 0); }
    function testFuzz_property(uint256 amount) public {
        // Ensure amount is reasonable (avoid overflow or huge gas costs)
        amount = bound(amount, 0, 1e30);

        // Call AdjustBetAmounts which sets betLimit = amount
        c.AdjustBetAmounts(amount);

        // The general rule: currentDifficulty() returns the difficulty value set via AdjustBetAmounts
        // AdjustBetAmounts only changes betLimit, but difficulty is unchanged.
        // Since difficulty was never set, it defaults to 0.
        // The property: currentDifficulty() always returns the same value regardless of AdjustBetAmounts input.
        assertTrue(c.currentDifficulty() == 0, "currentDifficulty should always be 0 after any AdjustBetAmounts call");
    }
}

